// Sprawdzenie flagi w pamięci przepływu
const loggingEnabled = flow.get("log_enabled") || false;

if (!loggingEnabled) {
    // Blokujemy przekazanie danych do Parser / CSV
    return null;
}

// Pobieramy tablicę obiektów {x, y}
var dataArray = msg.payload.variabledata;
var varName = msg.payload.variablename;   // np. "current_c"

// Tablica wyjściowa
var outputMsgs = [];

// Iterujemy po każdym punkcie pomiarowym w paczce
for (var i = 0; i < dataArray.length; i++) {
    var point = dataArray[i]; // Pojedynczy obiekt {x:..., y:...}

    outputMsgs.push({
        payload: {
            // x to timestamp wyliczony przez CubeMonitor (Unix ms)
            timestamp: point.x,

            // y to wartość zmiennej
            value: point.y,

            // nazwa zmiennej, żebyś wiedział co to za dane w CSV
            variable: varName
        }
    });
}

// Wypychamy serię wiadomości
return [outputMsgs];

