// Rozciągnięcie sygnału [-2, 2] do pełnego zakresu wykresu [-10, 10]
if (msg.payload && Array.isArray(msg.payload.variabledata)) {
    msg.payload.variabledata = msg.payload.variabledata.map(sample => {
        if (typeof sample === "object" && sample !== null) {
            let vKey = sample.y !== undefined ? "y" : (sample.value !== undefined ? "value" : "v");
            sample[vKey] = sample[vKey] * 5.0;
            return sample;
        }
        return sample * 5.0;
    });
}
return msg;

